-- Tab Perawatan: biaya Level 1 (BIAYA PERAWATAN = 11 item, BIAYA INFRA = 9 item) per BA/afd, YTD (Jan..bln laporan) dan bulan laporan; ribu Rp.
-- Ha/ton: MAX per afd per bulan (nilai berulang di tiap baris). Ha = bulan laporan; ton = jumlah bulanan. PMY = 2131+2122, afd B dikeluarkan.
-- Ganti '2026-09-01' (bulan laporan) dan batas BULAN< sesuai periode. Hasil: kolom 3 = JSON per afd -> work/r_rawat.json
WITH lv AS (SELECT column1 g, column2 l, column3 i FROM VALUES
('BIAYA PERAWATAN','HPT',0),('BIAYA PERAWATAN','PEMBERANTASAN LALANG',1),('BIAYA PERAWATAN','PENJARANGAN',2),('BIAYA PERAWATAN','PERALATAN KERJA RAWAT',3),('BIAYA PERAWATAN','PERAWATAN GAWANGAN',4),('BIAYA PERAWATAN','PIRINGAN, PASAR PIKUL, TPH',5),('BIAYA PERAWATAN','SENSUS TANAMAN',6),('BIAYA PERAWATAN','SISIP TANAMAN',7),('BIAYA PERAWATAN','SUPERVISI PEMELIHARAAN',8),('BIAYA PERAWATAN','TRANSPORT RAWAT',9),('BIAYA PERAWATAN','TUNASAN / PRUNING / SLASHING',10),
('BIAYA INFRA','MANAGEMENT MILL',11),('BIAYA INFRA','PEMELIHARAAN INFRASTRUKTUR LAINNYA',12),('BIAYA INFRA','PEMELIHARAAN JALAN',13),('BIAYA INFRA','PEMELIHARAAN JEMBATAN',14),('BIAYA INFRA','PEMELIHARAAN KONSERVASI TANAH',15),('BIAYA INFRA','PEMELIHARAAN PARIT',16),('BIAYA INFRA','PEMELIHARAAN TAPAK KUDA',17),('BIAYA INFRA','PRUNING PINGGIR JALAN',18),('BIAYA INFRA','SISIP JALAN',19)),
src AS (SELECT DECODE(KODE_BA,'2122','2131',KODE_BA) ba, KODE_AFD afd, BULAN, GROUP_LEVEL, LEVEL_1, RP_ACTUAL, RP_BUDGET, TON_ACTUAL, TON_BUDGET, HA_ACTUAL, HA_BUDGET
 FROM PRD_DB_PRESENTATION.PRS_COST.ESTATE_COST
 WHERE KODE_BA IN ('2121','2124','2131','2122') AND NOT (DECODE(KODE_BA,'2122','2131',KODE_BA)='2131' AND KODE_AFD='B') AND BULAN>='2026-01-01' AND BULAN<'2026-10-01'),
c AS (SELECT s.ba, s.afd, lv.i, ROUND(SUM(RP_ACTUAL)/1000) ya, ROUND(SUM(RP_BUDGET)/1000) yb, ROUND(SUM(IFF(BULAN='2026-09-01',RP_ACTUAL,0))/1000) ma, ROUND(SUM(IFF(BULAN='2026-09-01',RP_BUDGET,0))/1000) mb
 FROM src s JOIN lv ON s.GROUP_LEVEL=lv.g AND s.LEVEL_1=lv.l GROUP BY 1,2,3),
e AS (SELECT ba, afd, BULAN, MAX(TON_ACTUAL) t, MAX(TON_BUDGET) tb, MAX(HA_ACTUAL) h, MAX(HA_BUDGET) hb FROM src GROUP BY 1,2,3),
ea AS (SELECT ba, afd, ROUND(SUM(t),1) ty, ROUND(SUM(tb),1) tby, ROUND(SUM(IFF(BULAN='2026-09-01',t,0)),1) tm, ROUND(SUM(IFF(BULAN='2026-09-01',tb,0)),1) tbm, ROUND(SUM(IFF(BULAN='2026-09-01',h,0)),2) h, ROUND(SUM(IFF(BULAN='2026-09-01',hb,0)),2) hb FROM e GROUP BY 1,2)
SELECT ea.ba, ea.afd, OBJECT_CONSTRUCT('ton',ARRAY_CONSTRUCT(ty,tby,tm,tbm),'ha',ARRAY_CONSTRUCT(h,hb),
 'c',(SELECT ARRAY_AGG(ARRAY_CONSTRUCT(ya,yb,ma,mb)) WITHIN GROUP (ORDER BY i) FROM c WHERE c.ba=ea.ba AND c.afd=ea.afd))::STRING j
FROM ea ORDER BY 1,2;
